<?php $editing = !empty($request); ?>
<section class="page-hero compact"><div class="container"><span class="eyebrow">Scout Contribution</span><h1><?= $editing?'Edit / Resubmit Request':'Create Destination Post Request' ?></h1><p>All Scout content is reviewed by an Administrator before publication.</p></div></section>
<section class="section container"><div class="panel form-panel">
<?php if($editing && $request['admin_feedback']): ?><div class="feedback-box"><strong>Administrator feedback</strong><p><?= nl2br(e($request['admin_feedback'])) ?></p></div><?php endif; ?>
