<div class="form-actions"><a class="btn btn-soft" href="<?= e(url('scout/requests')) ?>">Cancel</a><button class="btn btn-primary" type="submit"><?= $editing?'Save & Resubmit':'Submit for Review' ?></button></div></form></div>
